```rust
//! A doubly linked list implemented with `unsafe` Rust.
//!
//! # Safety invariants
//!
//! - Every node is owned by exactly one `Box<Node<T>>`: either by
//!   `LinkedList::head` (for the first node) or by the `next` field of the
//!   node before it. The `prev` fields and the `LinkedList::tail` pointer are
//!   non-owning raw pointers.
//! - `LinkedList::head`, `LinkedList::tail` and every `Node::prev` always
//!   point either to `null` or to a node owned by the list.
//! - While a `Cursor` exists it holds the unique `&mut` to the list, so it is
//!   the only code that can access the nodes. Its `current` pointer always
//!   points to `null` or to a node owned by the list.
//! - `LinkedList::len` equals the number of nodes in the list.

mod pre_implemented;

use std::ptr;

struct Node<T> {
    element: T,
    /// Owning link to the next node.
    next: Option<Box<Node<T>>>,
    /// Non-owning link to the previous node. Stored as `*mut u8` so that the
    /// type stays covariant in `T` (raw `*mut Node<T>` would be invariant).
    prev: *mut u8,
}

pub struct LinkedList<T> {
    /// Owning handle to the first node.
    head: Option<Box<Node<T>>>,
    /// Non-owning pointer to the last node (stored as `*mut u8` for covariance).
    tail: *mut u8,
    len: usize,
}

pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    /// Pointer to the node the cursor is on, or null for an empty list.
    current: *mut u8,
}

pub struct Iter<'a, T> {
    current: Option<&'a Node<T>>,
}

// The list only shares data through raw pointers that point to nodes it owns,
// so it is `Send`/`Sync` exactly when `T` is.
unsafe impl<T: Send> Send for LinkedList<T> {}
unsafe impl<T: Sync> Sync for LinkedList<T> {}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // `head` owns the whole node chain through the `next` `Box`es, so
        // dropping it recursively drops every node. `tail` and the `prev`
        // pointers are non-owning and need no cleanup.
        self.head = None;
        self.tail = ptr::null_mut();
        self.len = 0;
    }
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: ptr::null_mut(),
            len: 0,
        }
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self
            .head
            .as_ref()
            .map(|node| node.as_ptr() as *mut u8)
            .unwrap_or(ptr::null_mut());
        Cursor { list: self, current }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.tail;
        Cursor { list: self, current }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            current: self.head.as_deref(),
        }
    }
}

impl<'a, T> Cursor<'a, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        if self.current.is_null() {
            None
        } else {
            // Safety: `current` points to a node owned by `self.list`, and the
            // cursor holds the unique `&mut` to the list, so no other reference
            // to this node can exist.
            Some(unsafe { &mut (*self.current as *mut Node<T>).element })
        }
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let current = self.current;
        if current.is_null() {
            return None;
        }
        // Safety: `current` points to a node owned by `self.list`; reading its
        // `next` pointer is a plain read that creates no aliasing `&mut`.
        let next = unsafe { (*current as *mut Node<T>).next.as_ref() }
            .map(|node| node.as_ptr() as *mut u8)
            .unwrap_or(ptr::null_mut());
        self.current = next;
        if self.current.is_null() {
            None
        } else {
            // Safety: as in `peek_mut`; the cursor now points at `next`.
            Some(unsafe { &mut (*self.current as *mut Node<T>).element })
        }
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        let current = self.current;
        if current.is_null() {
            return None;
        }
        // Safety: `current` points to a node owned by `self.list`; reading its
        // non-owning `prev` pointer creates no aliasing `&mut`.
        let prev = unsafe { (*current as *mut Node<T>).prev };
        self.current = prev;
        if self.current.is_null() {
            None
        } else {
            // Safety: as in `peek_mut`; the cursor now points at `prev`.
            Some(unsafe { &mut (*self.current as *mut Node<T>).element })
        }
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let current = self.current;
        if current.is_null() {
            return None;
        }
        let current = current as *mut Node<T>;

        // Safety: `current` points to a node owned by `self.list`; we only read
        // its links here.
        let (prev, next) = unsafe {
            (
                (*current).prev,
                (*current)
                    .next
                    .as_ref()
                    .map(|node| node.as_ptr() as *mut u8)
                    .unwrap_or(ptr::null_mut()),
            )
        };

        let list = &mut *self.list;
        if prev.is_null() {
            // `current` is the head.
            // Safety: moving the owning `next` `Box` into `head`.
            list.head = unsafe { (*current).next.take() };
        } else {
            // Safety: relinking the previous node's owning `next` to skip `current`.
            unsafe { (*(prev as *mut Node<T>)).next = (*current).next.take() };
        }
        if next.is_null() {
            // `current` is the tail.
            list.tail = prev;
        } else {
            // Safety: relinking the next node's non-owning `prev` to skip `current`.
            unsafe { (*(next as *mut Node<T>)).prev = prev };
        }
        list.len -= 1;

        // Move the cursor to the neighbour closest to the back.
        self.current = if next.is_null() { prev } else { next };

        // Safety: `current` is now unlinked. Its `next` field is `None` (moved
        // out above) and its `prev` field is non-owning, so `element` is the
        // only field with a destructor. We read it out (a move) and free the
        // allocation without dropping `element` a second time.
        Some(unsafe {
            let element = std::ptr::read(&(*current).element);
            let layout = std::alloc::Layout::new::<Node<T>>().unwrap();
            std::alloc::dealloc(current.cast(), layout);
            element
        })
    }

    pub fn insert_after(&mut self, element: T) {
        let new_node = Box::new(Node {
            element,
            next: None,
            prev: ptr::null_mut(),
        });
        let new = Box::as_ptr(&new_node) as *mut u8;
        let list = &mut *self.list;

        if self.current.is_null() {
            // Empty list: the new node becomes both head and tail.
            list.head = Some(new_node);
            list.tail = new;
            list.len = 1;
            self.current = new;
            return;
        }

        let current = self.current as *mut Node<T>;
        // Safety: `current` points to a node owned by `self.list`.
        let old_next = unsafe { (*current).next.take() };
        let old_next_ptr = old_next.as_ref().map(|node| node.as_ptr() as *mut u8);
        // Safety: splicing the new node between `current` and `old_next`.
        unsafe {
            (*current).next = Some(new_node);
            (*(new as *mut Node<T>)).prev = self.current;
            (*(new as *mut Node<T>)).next = old_next;
        }
        if let Some(old_next_ptr) = old_next_ptr {
            // Safety: `old_next_ptr` points to a node owned by the list.
            unsafe { (*(old_next_ptr as *mut Node<T>)).prev = new };
        }
        if list.tail == self.current {
            list.tail = new;
        }
        list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new_node = Box::new(Node {
            element,
            next: None,
            prev: ptr::null_mut(),
        });
        let new = Box::as_ptr(&new_node) as *mut u8;
        let list = &mut *self.list;

        if self.current.is_null() {
            // Empty list: the new node becomes both head and tail.
            list.head = Some(new_node);
            list.tail = new;
            list.len = 1;
            self.current = new;
            return;
        }

        let current = self.current as *mut Node<T>;
        // Safety: `current` points to a node owned by `self.list`.
        let prev = unsafe { (*current).prev };
        if prev.is_null() {
            // `current` is the head.
            let old_head = list.head.take();
            // Safety: splicing the new node in front of `current` (the old head).
            unsafe {
                (*(new as *mut Node<T>)).next = old_head;
                (*current).prev = new;
            }
            list.head = Some(new_node);
        } else {
            let prev_node = prev as *mut Node<T>;
            // Safety: moving the owning `next` `Box` out of `prev` and splicing.
            let current_box = unsafe { (*prev_node).next.take() };
            unsafe {
                (*(new as *mut Node<T>)).prev = prev;
                (*(new as *mut Node<T>)).next = current_box;
                (*prev_node).next = Some(new_node);
                (*current).prev = new;
            }
        }
        list.len += 1;
    }
}

