    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let current = self.current;
        if current.is_null() {
            return None;
        }
        let current = current as *mut Node<T>;

        // Safety: `current` points to a node owned by `self.list`; we only read
        // its links here.
        let (prev, next) = unsafe {
            (
                (*current).prev,
                (*current)
                    .next
                    .as_ref()
                    .map(|node| node.as_ptr() as *mut u8)
                    .unwrap_or(ptr::null_mut()),
            )
        };

        let list = &mut *self.list;
        if prev.is_null() {
            // `current` is the head.
            // Safety: transfers ownership of the `next` node into `head`.
            list.head = unsafe { (*current).next.take() };
        } else {
            // Safety: relinks the previous node's owning `next` link to skip `current`.
            unsafe {
                (*(prev as *mut Node<T>)).next = (*current).next.take()
            };
        }
        if next.is_null() {
            // `current` is the tail.
            list.tail = prev;
        } else {
            // Safety: relinks the next node's non-owning `prev` link to skip `current`.
            unsafe { (*(next as *mut Node<T>)).prev = prev };
        }
        list.len -= 1;

        // Move the cursor to the neighboring element closest to the back.
        self.current = if next.is_null() { prev } else { next };

        // Safety: `current` is now unlinked from the list. Its `next` field is
        // `None` (moved out above) and its `prev` field is non-owning, so
        // `element` is the only field with a destructor. We move it out with
        // `ptr::read` and free the allocation without dropping `element` a
