/// Price in cents of a group of `n` distinct books from the series.
///
/// 1 book: $8.00, 2: 5% off, 3: 10% off, 4: 20% off, 5: 25% off.
const GROUP_PRICES: [u32; 6] = [0, 800, 1520, 2160, 2560, 3000];

/// Calculates the lowest possible price of a basket of books from the
/// 5-book series, in cents, giving as big a discount as possible.
pub fn lowest_price(books: &[u32]) -> u32 {
    let mut counts = [0u32; 5];
    for &book in books {
        if (1..=5).contains(&book) {
            counts[book as usize - 1] += 1;
        }
    }

    // Ascending: counts[0] is the smallest, counts[4] the largest copy count.
    counts.sort_unstable();

    // Level-based grouping: at level `i` (1..=most copies), every title with
    // at least `i` copies contributes one book to a group, so the group size
    // is the number of titles with count >= `i`.
    let mut total = 0u32;
    for level in 1..=counts[4] {
        let group_size = counts.iter().filter(|&&count| count >= level).count();
        total += GROUP_PRICES[group_size];
    }

    // A 5-group plus a 3-group costs 5160; splitting them into two 4-groups
    // costs 5120, saving 40. Do this as often as possible: limited by the
    // number of 5-groups (levels where all five titles are present, i.e. the
    // smallest count) and the number of 3-groups (levels with exactly three
    // titles present).
    let fives = counts[0];
    let threes = counts[2] - counts[1];
    total - 40 * fives.min(threes)
}

#[cfg(test)]
mod tests {
    use super::lowest_price;

    /// Exact brute force: minimum over all ways of partitioning the basket
    /// into groups of distinct titles, memoized over count vectors.
    fn brute_force(books: &[u32]) -> u32 {
        use std::collections::HashMap;

        let mut counts = [0u32; 5];
        for &book in books {
            if (1..=5).contains(&book) {
                counts[book as usize - 1] += 1;
            }
        }

        let mut memo: HashMap<[u32; 5], u32> = HashMap::new();
        let mut solve = |counts: [u32; 5]| -> u32 {
            if counts.iter().all(|&count| count == 0) {
                return 0;
            }
            if let Some(&value) = memo.get(&counts) {
                return value;
            }
            let mut best = u32::MAX;
            for mask in 1..32 {
                let mut next = counts;
                let mut size = 0usize;
                let mut valid = true;
                for title in 0..5 {
                    if mask & (1 << title) != 0 {
                        if next[title] == 0 {
                            valid = false;
                            break;
                        }
                        next[title] -= 1;
                        size += 1;
                    }
                }
                if valid {
                    best = best.min(GROUP_PRICES[size] + solve(next));
                }
            }
            memo.insert(counts, best);
            best
        };
        solve(counts)
    }

    #[test]
    fn fuzz_matches_brute_force() {
        // Deterministic LCG so the fuzz test is reproducible.
        let mut seed: u64 = 0x9E3779B97F4A7C15;
        let mut next = move || {
            seed = seed
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            (seed >> 33) as u32
        };

        for _ in 0..2000 {
            let mut books = Vec::new();
            for _ in 0..(next() % 12) {
                books.push(1 + next() % 5);
            }
            assert_eq!(
                lowest_price(&books),
                brute_force(&books),
                "mismatch for basket {books:?}"
            );
        }
    }
}
