/// Unrolled version of heap's algorithm due to Sedgewick
fn heap_unrolled_<T, F, C>(n: usize, xs: &mut [T], f: &mut F) -> C
    where F: FnMut(&mut [T]) -> C,
          C: ControlFlow,
{
